{% set units = [
  'W', 'kW', 'Wh', 'kWh', 'V', 'A',
  'Вт', 'кВт', 'Вт·ч', 'кВт·ч', 'В', 'А'
] %}
{% set ns = namespace(sensors=[]) %}

{% for s in states.sensor %}
  {% set unit = s.attributes.get('unit_of_measurement') %}
  {% if unit in units %}
    {% set did = device_id(s.entity_id) %}
    {% set dname = (
      device_attr(did, 'name_by_user')
      or device_attr(did, 'name')
    ) if did else none %}

    {% set ns.sensors = ns.sensors + [{
      'entity_id': s.entity_id,
      'name': s.name,
      'state': s.state,
      'unit': unit,
      'device_class': s.attributes.get('device_class'),
      'state_class': s.attributes.get('state_class'),
      'device_id': did,
      'device_name': dname,
      'area_id': area_id(s.entity_id),
      'area_name': area_name(s.entity_id),
      'last_updated': s.last_updated.isoformat()
    }] %}
  {% endif %}
{% endfor %}

{{ {'sensors': ns.sensors} | to_json }}

parameters.jsCode:
const units = {
  W: 'power', kW: 'power',
  Wh: 'energy', kWh: 'energy',
  V: 'voltage', A: 'current',
  'Вт': 'power', 'кВт': 'power',
  'Вт·ч': 'energy', 'кВт·ч': 'energy',
  'В': 'voltage', 'А': 'current',
};

// Подтверждённые связи месячных счётчиков с источниками.
const monthlySources = {
  'sensor.sockets_kitchen': 'sensor.sockets_kitchen_energy',
  'sensor.sockets_bath': 'sensor.sockets_bath_energy',
};

const sourceIds = new Set(Object.values(monthlySources));

const sensors = $input.all().flatMap(item => {
  let payload = item.json.data ?? item.json.body ?? item.json;

  if (typeof payload === 'string') {
    payload = JSON.parse(payload);
  }

  if (!Array.isArray(payload.sensors)) {
    throw new Error('В ответе HTTP Request отсутствует массив sensors');
  }

  return payload.sensors;
});

// Убираем возможные повторения одной сущности.
const byId = new Map(
  sensors.map(sensor => [sensor.entity_id, sensor])
);

const areas = new Map();
const deviceIds = new Set();

const countsByMetric = {
  power: 0,
  energy: 0,
  voltage: 0,
  current: 0,
};

let sensorCount = 0;
let unassignedCount = 0;
let withoutAreaCount = 0;

for (const sensor of byId.values()) {
  if (!Object.hasOwn(units, sensor.unit)) continue;

  const sourceId = monthlySources[sensor.entity_id] ?? null;
  const source = sourceId ? byId.get(sourceId) : null;

  // Привязки самой сущности имеют приоритет.
  // Источник используется только для известных месячных счётчиков.
  const deviceId = sensor.device_id ?? source?.device_id ?? null;

  const deviceName = sensor.device_id
    ? sensor.device_name
    : source?.device_name;

  const areaId = sensor.area_id ?? source?.area_id ?? null;

  const areaName = sensor.area_id
    ? sensor.area_name
    : source?.area_name;

  const metric = units[sensor.unit];
  const state = sensor.state;

  const numeric =
    state !== null &&
    state !== undefined &&
    String(state).trim() !== ''
      ? Number(state)
      : NaN;

  const reading = {
    entity_id: sensor.entity_id,
    name: sensor.name,
    metric,
    value: Number.isFinite(numeric) ? numeric : null,
    unit: sensor.unit,
    state,
    device_class: sensor.device_class ?? null,
    state_class: sensor.state_class ?? null,
    energy_role: sourceId
      ? 'monthly'
      : sourceIds.has(sensor.entity_id)
        ? 'source'
        : null,
    source_entity_id: sourceId,
    device_binding: sensor.device_id
      ? 'ha'
      : deviceId
        ? 'confirmed_source'
        : null,
    area_binding: sensor.area_id
      ? 'ha'
      : areaId
        ? 'confirmed_source'
        : null,
    last_updated: sensor.last_updated ?? null,
  };

  // null используется как ключ группы без помещения.
  if (!areas.has(areaId)) {
    areas.set(areaId, {
      area_id: areaId,
      area_name: areaName ?? areaId ?? 'Без помещения',
      sensor_count: 0,
      devices: new Map(),
      unassigned: [],
    });
  }

  const area = areas.get(areaId);

  sensorCount++;
  area.sensor_count++;
  countsByMetric[metric]++;

  if (!areaId) withoutAreaCount++;

  if (!deviceId) {
    area.unassigned.push(reading);
    unassignedCount++;
    continue;
  }

  deviceIds.add(deviceId);

  if (!area.devices.has(deviceId)) {
    area.devices.set(deviceId, {
      device_id: deviceId,
      device_name: deviceName ?? deviceId,
      readings: [],
    });
  }

  area.devices.get(deviceId).readings.push(reading);
}

const sortReadings = readings =>
  readings.sort((a, b) => a.entity_id.localeCompare(b.entity_id));

const resultAreas = [...areas.values()].map(area => {
  const devices = [...area.devices.values()];

  for (const device of devices) {
    sortReadings(device.readings);
    device.sensor_count = device.readings.length;
  }

  devices.sort((a, b) =>
    a.device_name.localeCompare(b.device_name, 'ru')
  );

  return {
    area_id: area.area_id,
    area_name: area.area_name,
    sensor_count: area.sensor_count,
    device_count: devices.length,
    devices,
    unassigned: sortReadings(area.unassigned),
  };
});

resultAreas.sort((a, b) => {
  if (a.area_id === null) return b.area_id === null ? 0 : 1;
  if (b.area_id === null) return -1;

  return a.area_name.localeCompare(b.area_name, 'ru');
});

return [{
  json: {
    received_at: new Date().toISOString(),
    sensor_count: sensorCount,
    device_count: deviceIds.size,
    area_count: resultAreas.filter(area => area.area_id !== null).length,
    counts_by_metric: countsByMetric,
    without_area_sensor_count: withoutAreaCount,
    unassigned_device_sensor_count: unassignedCount,
    areas: resultAreas,
  },
}];
